const mode = $('Prepare Text Input').first().json['Study Mode'];
let rawOutput = $input.first().json.output;

console.log('Mode:', mode);
console.log('Raw output type:', typeof rawOutput);

// Parse string output from AI Agent
if (typeof rawOutput === 'string') {
  const cleaned = rawOutput
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  try {
    rawOutput = JSON.parse(cleaned);
  } catch(e) {
    throw new Error('Failed to parse AI output: ' + e.message);
  }
}

// Extract fullData regardless of nesting
let fullData;
if (Array.isArray(rawOutput)) {
  fullData = rawOutput;
} else if (rawOutput && rawOutput.data) {
  fullData = rawOutput.data;
} else {
  fullData = rawOutput;
}

console.log('fullData is array:', Array.isArray(fullData));
console.log('fullData keys:', Array.isArray(fullData) ? 'array[' + fullData.length + ']' : Object.keys(fullData || {}));

// Build filteredData matching Lovable's exact expected shapes
let filteredData;

switch(mode) {
  case 'summary':
    // Must be object with exactly: topics, definitions, takeaways
    filteredData = {
      topics: Array.isArray(fullData.topics) ? fullData.topics : [],
      definitions: Array.isArray(fullData.definitions) ? fullData.definitions : [],
      takeaways: Array.isArray(fullData.takeaways) ? fullData.takeaways : []
    };
    break;

  case 'flashcards':
    // Must be a direct array of { question, answer }
    if (Array.isArray(fullData)) {
      filteredData = fullData;
    } else if (Array.isArray(fullData.flashcards)) {
      filteredData = fullData.flashcards;
    } else {
      filteredData = [];
    }
    break;

  case 'quiz':
    // Must be a direct array of { question, options, answer }
    // answer must exactly match one of the options strings
    let quizArray;
    if (Array.isArray(fullData)) {
      quizArray = fullData;
    } else if (Array.isArray(fullData.quiz)) {
      quizArray = fullData.quiz;
    } else {
      quizArray = [];
    }

    // Sanitize each question — strip any A. B. C. D. prefixes
    filteredData = quizArray.map(q => {
      const cleanOptions = (q.options || []).map(opt =>
        opt.replace(/^[A-D]\.\s*/i, '').trim()
      );
      const cleanAnswer = (q.answer || '').replace(/^[A-D]\.\s*/i, '').trim();

      // Verify answer matches one of the options
      const answerMatches = cleanOptions.includes(cleanAnswer);
      console.log('Q:', q.question.slice(0, 50), '| Answer matches:', answerMatches);

      return {
        question: q.question,
        options: cleanOptions,
        answer: answerMatches ? cleanAnswer : cleanOptions[0]
      };
    });
    break;

  default:
    filteredData = fullData;
}

// Final validation
console.log('Filtered data type:', Array.isArray(filteredData) ? 'array[' + filteredData.length + ']' : typeof filteredData);

return {
  json: {
    success: true,
    mode: mode,
    subject: $('Prepare Text Input').first().json.Subject,
    gradeLevel: $('Prepare Text Input').first().json['Grade Level'],
    data: filteredData
  }
};

